record.field:
trsp_amount = 0
for fp in payslip.version_id.fixed_premiums_ids:
    if fp.input_type_id.code == 'TRSP':
        trsp_amount = fp.amount
        break
bonus_legal = employee.company_id.bonus_transport or 30000
if not trsp_amount:
    trsp_amount = bonus_legal
result = min(trsp_amount, bonus_legal) * TX

hiring_date = employee.hiring_date or (version.date_start if version else None)
if not hiring_date:
    result = 0
else:
    payslip_date = payslip.date_from
    years = payslip_date.year - hiring_date.year
    if (payslip_date.month, payslip_date.day) < (hiring_date.month, hiring_date.day):
        years -= 1
    anciennete = years
    salaire_categoriel = version.wage
    if anciennete < 2:
        taux = 0
    else:
        taux = 2 + int(anciennete - 2)
        if taux > 25:
            taux = 25
    result = salaire_categoriel * (taux / 100)
